#!/usr/bin/env node
/**
 * Single vN+1 amendment request for the EXISTING permanent John mandate.
 * PREPARE, then Supabase-authenticated owner decision via the already-live
 * JHN consent page. No principal signature in this CLI; no mandate issuance,
 * provider effect or per-action authorization generated by this command.
 */
import {readFileSync,realpathSync,statSync} from "node:fs";
import {openExistingJohnCopStore} from "../lib/john-cop-existing-store.js";
import {createSqliteCopEventStore} from
  "../../../inseme/packages/cop-core/src/sqlite-cop-event-store.js";
import {resolveMandate} from
  "../../../inseme/packages/cop-core/src/governed-act.js";
import {createOfflineJohnIssuerVerifier} from "../lib/john-offline-issuer-verifier.js";
import {sshFingerprint} from "../lib/john-sshsig-approval.js";
import {createJhnCanonicalConsentWorkflow} from "../lib/jhn-canonical-consent-workflow.js";
import {johnStandingMandatePlan} from "../lib/jhn-standing-mandate-plan.js";

const PATH="/var/lib/cogentia/cop/john-root-v1.sqlite";
const KEY_PATH="/home/ubuntu/.ssh/authorized_keys";
const FINGERPRINT="SHA256:lG9BC3fIjurrBccYLO1w7VQpmc9ZMr8MvM1o3zJ6L3c";
const REF="mandate:jhn:john-root";
const fail=(error)=>({ok:false,error,challenge_created:false,mandate_amended:false});
function issuerVerified(store) {
  let publicKey;
  try{
    publicKey=readFileSync(KEY_PATH,"utf8").split("\n").find(line=>{
      try{return sshFingerprint(line)===FINGERPRINT;}catch{return false;}
    });
  }catch{return false;}
  if(!publicKey)return false;
  const current=resolveMandate(store,REF);
  try{
    return createOfflineJohnIssuerVerifier({
      trustedSshPublicKey:publicKey,expectedSshFingerprint:FINGERPRINT,
    })({mandate:current,mandate_ref:REF,store}).verified===true;
  }catch{return false;}
}
export async function runStandingConsentCli({
  args=process.argv.slice(2),
  ownerShell=Boolean(process.env.SSH_CONNECTION),
  path=PATH,verifyIssuer=issuerVerified,
}={}){
  if(args.length!==1||!["--plan","--request"].includes(args[0]))
    return fail("usage: --plan|--request");
  // Only preparation is allowed for a non-owner process. The decision
  // itself must be performed from an independently authenticated JHN session.
  if(args[0]==="--request"&&!ownerShell)
    return fail("owner_ssh_session_required");
  let store,opened;
  try{
    if(realpathSync(path)!==path||!statSync(path).isFile())
      return fail("canonical_store_path_invalid");
    if(args[0]==="--request")store=createSqliteCopEventStore(path);
    else{
      opened=openExistingJohnCopStore(path);
      if(!opened.ok)return fail(opened.error);
      store=opened.store;
    }
    if(!verifyIssuer(store))return fail("canonical_issuer_unverified");
    const plan=johnStandingMandatePlan({store});
    if(!plan.ok||plan.already_authorized_in_scope)return plan;
    if(args[0]==="--plan")return {...plan,challenge_created:false};
    const workflow=createJhnCanonicalConsentWorkflow({store});
    const created=workflow.request({mandate:plan.mandate,ttl_ms:600000});
    if(!created.ok)return fail(created.error||"standing_consent_request_failed");
    const check=workflow.inspect({challenge_id:created.challenge_id});
    if(!check.ok||check.status!=="pending"||
       check.payload_hash!==created.payload_hash)
      return fail("standing_challenge_receipt_unconfirmed");
    return {ok:true,challenge_created:true,mandate_amended:false,
      execution:false,mandate_ref:REF,previous_version:plan.previous_version,
      next_version:plan.next_version,
      added_capabilities:plan.added_capabilities,
      budget_snapshot_for_review:plan.budget_snapshot_for_review,
      url:"https://jhn.baronsmariani.org/cop/consent/"+created.challenge_id,
      challenge_id:created.challenge_id,payload_hash:created.payload_hash,
      expires_at:created.expires_at,requires_supabase_principal_decision:true};
  }catch(e){return fail("canonical_standing_request_unavailable");}
  finally{opened?.close();if(args[0]==="--request")store?.close();}
}
if(process.argv[1]&&import.meta.url===new URL("file://"+process.argv[1]).href){
  const result=await runStandingConsentCli();
  console.log(JSON.stringify(result,null,2));
  if(!result.ok)process.exitCode=1;
}
